export const nfcCheckInTopic = function nfcCheckInTopic(
  presenceMode: HelpPresenceMode,
  nfcEnabled: boolean | null,
): HelpTopic {
  if (nfcEnabled === null || presenceMode === "unknown") {
    return unknownNfcTopic(
      HELP_TOPICS.nfcCheckIn,
      "Kinder mit dem Armband ein- und auschecken",
      "Wie checken sich Kinder mit dem Armband ein und aus?",
      "Scan",
      [HELP_TOPICS.webAttendance, HELP_TOPICS.nfcProblem],
    );
  }
  if (!nfcEnabled) {
    return unavailableNfcTopic(
      HELP_TOPICS.nfcCheckIn,
      "Kinder mit dem Armband ein- und auschecken",
      "Wie checken sich Kinder mit dem Armband ein und aus?",
      "Scan",
      [HELP_TOPICS.webAttendance, HELP_TOPICS.nfcProblem],
    );
  }

  if (presenceMode === "binary") {
    return {
      id: HELP_TOPICS.nfcCheckIn,
      title: "Kinder mit dem Armband ein- und auschecken",
      question: "Wie checken sich Kinder mit dem Armband ein und aus?",
      // Der Server schaltet bei einfacher Anwesenheit nur die Anwesenheit um
      // (`scanBinary`) und antwortet mit "Willkommen, ..." bzw. "Tschuess,
      // ...". Raum und taegliche Abmeldung sind in der Antwort leer bzw.
      // aus. Das Scannen selbst funktioniert also unveraendert.
      summary:
        "Kinder melden sich mit ihrem Armband an und ab. moto hält fest, ob ein Kind da ist.",
      group: "nfc",
      audience: ["caregiver", "lead"],
      icon: "Scan",
      requirements: [
        "Das Armband ist dem Kind zugewiesen.",
        "Am Tablet ist der Scan-Bildschirm geöffnet.",
      ],
      steps: [],
      instructionGroups: [
        {
          title: "Anmelden",
          steps: [
            "Das Kind hält sein Armband an den NFC-Sensor.",
            "moto bestätigt mit dem Namen des Kindes.",
          ],
        },
        {
          title: "Abmelden",
          steps: [
            "Das angemeldete Kind hält sein Armband erneut an den Sensor.",
            "moto meldet das Kind ab und bestätigt mit seinem Namen.",
          ],
        },
      ],
      result:
        "moto zeigt `Anwesend` oder `Zuhause`. Räume werden nicht erfasst.",
      differences: [
        "Die Frage `Wohin geht ...?` erscheint nicht. Das zweite Scannen meldet das Kind direkt ab.",
        "Eine Auswahl von Raum oder Aktivität am Tablet ändert nichts an der Anwesenheit.",
      ],
      troubleshooting: HELP_TOPICS.nfcProblem,
      related: [HELP_TOPICS.tagAssignment, HELP_TOPICS.webAttendance],
    };
  }

  return {
    id: HELP_TOPICS.nfcCheckIn,
    title: "Kinder mit dem Armband ein- und auschecken",
    question: "Wie checken sich Kinder mit dem Armband ein und aus?",
    summary:
      "Kinder melden sich mit ihrem Armband bei einer Aufsicht an. Danach wählen sie ihr nächstes Ziel.",
    group: "nfc",
    audience: ["caregiver", "lead"],
    icon: "Scan",
    requirements: [
      "Das Armband ist dem Kind zugewiesen.",
      "Am Tablet läuft eine Aufsicht.",
    ],
    steps: [],
    instructionGroups: [
      {
        title: "Einchecken",
        steps: [
          "Das Kind hält sein Armband an den NFC-Sensor.",
          "Prüfe die grüne Bestätigung mit Name, Abholzeit und Raum.",
          "Warte, bis sich die Anzeige automatisch schließt.",
        ],
      },
      {
        title: "Auschecken oder den Ort wechseln",
        steps: [
          "Das bereits eingecheckte Kind hält sein Armband erneut an den Sensor.",
          "Das Kind wählt unter `Wohin geht ...?` das passende Ziel.",
          "Wähle `Raumwechsel` für einen anderen betreuten Raum. Dort hält das Kind sein Armband erneut an.",
          "Offene Räume stehen mit ihrem Namen da, zum Beispiel `Turnhalle`. Ein Tipp trägt das Kind sofort dort ein.",
          "Wähle `nach Hause`, wenn das Kind die OGS verlässt.",
          "Je nach Einstellung können auch `Schulhof` oder `Toilette` erscheinen.",
        ],
      },
    ],
    result:
      "moto aktualisiert den Aufenthaltsort. Bei einem Ortswechsel bleibt das Kind angemeldet. Erst nach `nach Hause` ist es abgemeldet.",
    differences: [
      "Welche Ziele angezeigt werden, legt deine OGS fest.",
      "Ein offener Raum erscheint nur, wenn die Leitung ihn unter `Räume` als `Offener Raum` freigegeben hat. Dort braucht es kein Tablet und keine Aufsicht.",
      "Eine tägliche Abmeldezeit kann verhindern, dass `nach Hause` zu früh gewählt wird.",
      "Nach dem Abmelden kann ein freiwilliges Tages-Feedback erscheinen.",
    ],
    troubleshooting: HELP_TOPICS.nfcProblem,
    related: [HELP_TOPICS.tagAssignment, HELP_TOPICS.nfcSupervision],
  };
} satisfies typeof authored_nfcCheckInTopic;

export const nfcProblemTopic = function nfcProblemTopic(
  nfcEnabled: boolean | null,
): HelpTopic {
  if (nfcEnabled === null) {
    return unknownNfcTopic(
      HELP_TOPICS.nfcProblem,
      "Das NFC-Tablet funktioniert nicht",
      "Was kann ich tun, wenn das NFC-Tablet nicht funktioniert?",
      "TabletSmartphone",
      [HELP_TOPICS.webAttendance, HELP_TOPICS.trackWorkTime],
      "probleme",
    );
  }
  if (!nfcEnabled) {
    return unavailableNfcTopic(
      HELP_TOPICS.nfcProblem,
      "Das NFC-Tablet funktioniert nicht",
      "Was kann ich tun, wenn das NFC-Tablet nicht funktioniert?",
      "TabletSmartphone",
      [HELP_TOPICS.webAttendance, HELP_TOPICS.trackWorkTime],
      "probleme",
    );
  }

  return {
    id: HELP_TOPICS.nfcProblem,
    title: "Das NFC-Tablet funktioniert nicht",
    question: "Was kann ich tun, wenn das NFC-Tablet nicht funktioniert?",
    summary: "Prüfe Strom, Verbindung, Lesegerät und Armband nacheinander.",
    group: "probleme",
    audience: ["caregiver", "lead"],
    icon: "TabletSmartphone",
    steps: [
      "Prüfe, ob Tablet und NFC-Sensor Strom haben.",
      "Prüfe, ob das Tablet mit dem Internet verbunden ist.",
      "Lege das Armband flach und für einen kurzen Moment auf den NFC-Sensor.",
      "Teste ein zweites, sicher funktionierendes Armband.",
      "Melde dich mit der Geräte-PIN an und öffne `Armband identifizieren`.",
      "Prüfe dort, ob das Armband erkannt und der richtigen Person zugewiesen ist.",
      "Starte das Tablet neu, wenn weiterhin kein Armband erkannt wird.",
      "Hilft nichts davon? Gib die Fehlermeldung an deine Leitung oder an das moto-Team weiter.",
    ],
    result:
      "Der Vergleich grenzt die Ursache ein. Das Problem liegt am Armband oder am Tablet.",
    differences: [
      "Wird nur ein Armband nicht erkannt, prüfe oder erneuere dessen Zuweisung.",
      "Werden keine Armbänder erkannt, prüfe besonders NFC-Sensor, Kabel und Gerätestatus.",
      "Bei einem Ausfall können berechtigte Personen Anwesenheit und Arbeitszeit vorübergehend in der moto-App erfassen.",
    ],
    related: [HELP_TOPICS.tagAssignment, HELP_TOPICS.nfcCheckIn],
  };
} satisfies typeof authored_nfcProblemTopic;

/**
 * Der Bereich `Geräte` der Einstellungen. Alle diese Schalter haengen an NFC
 * (`DependsOn` in backend/services/config/defaults/devices.go und
 * operations.go), stehen bei
 * einfacher Anwesenheit aber trotzdem da: `scanBinary` schaltet nur die
 * Anwesenheit um und fragt kein Ziel ab. Deshalb sagt der Artikel das zuerst.
 */
export const nfcSettingsTopic = function nfcSettingsTopic(
  presenceMode: HelpPresenceMode,
): HelpTopic {
  const tracksRooms = presenceMode !== "binary";
  return {
    id: HELP_TOPICS.leadNfcSettings,
    title: "Einstellen, was das Tablet anzeigt",
    question: "Wo stelle ich die NFC-Tablets ein?",
    summary: tracksRooms
      ? "Du setzt die Geräte-PIN und legst fest, wohin Kinder auschecken dürfen."
      : "Du setzt die PIN, mit der sich dein Team am Tablet anmeldet.",
    group: "nfc",
    audience: "lead",
    icon: "SlidersHorizontal",
    steps: [],
    instructionGroups: [
      {
        title: "Die Geräte-PIN setzen",
        description:
          "Ohne Geräte-PIN kann sich dein Team nicht am Tablet anmelden. Lege die PIN vor dem ersten Betreuungstag fest.",
        steps: [
          "Wähle unten in der Seitenleiste `Einstellungen`.",
          "Wähle den Bereich `Geräte`.",
          "Trage unter `Geräte-PIN` eine vierstellige Zahl ein. Leichte PINs wie 1234, 1111 oder 1212 nimmt moto nicht an.",
          "Gib die neue PIN an dein Team weiter.",
        ],
      },
      ...(tracksRooms
        ? [
            {
              title: "Die Ziele beim Auschecken festlegen",
              description:
                "Diese Schalter bestimmen, welche Knöpfe ein Kind am Tablet sieht, wenn es sein Armband ein zweites Mal auflegt.",
              steps: [
                "Bleibe im Bereich `Geräte`.",
                "Schalte `„Raumwechsel“ am Tablet anbieten` ein, wenn Kinder den Raum wechseln dürfen.",
                "Schalte `„Schulhof“ am Tablet anbieten` und `„Toilette“ am Tablet anbieten` nach Bedarf ein.",
              ],
              ordered: false,
            },
            {
              title: "Festlegen, ab wann Kinder nach Hause dürfen",
              description:
                "Alles dazu steht im Bereich `Geräte` unter `„Nach Hause“ am Tablet`.",
              steps: [
                "Trage bei `„Nach Hause“ ab Uhrzeit` eine Uhrzeit ein. Bei `Jederzeit` geht `nach Hause` den ganzen Tag.",
                "Soll die Abholzeit jedes Kindes zählen? Dann schalte `Abholzeit jedes Kindes beachten` ein.",
                "Trage bei `„Nach Hause“ vor der Abholzeit (Minuten)` ein, wie früh das Kind gehen darf. Bei 15 Minuten und Abholzeit 16:00 geht es ab 15:45.",
                "Schalte `„Nach Hause“ in jedem Raum anzeigen` aus, wenn Kinder nur aus dem Gruppenraum und vom Schulhof nach Hause dürfen.",
              ],
            },
          ]
        : []),
    ],
    result:
      "moto speichert jede Änderung sofort. Das Tablet übernimmt sie beim nächsten Start.",
    notes: [
      "Findest du eine Einstellung nicht? Nutze oben `Einstellung suchen`.",
      ...(tracksRooms
        ? [
            "`Schulhof` und `Toilette` legen jeweils einen passenden Raum mit an.",
            "`Name und Belegung bei vollem Raum` nennt am Tablet, welcher Raum voll ist.",
          ]
        : []),
    ],
    differences: [
      // Der Grund, warum eine OGS mit einfacher Anwesenheit hier fast nichts
      // einstellen kann: das Tablet fragt kein Ziel ab.
      ...(presenceMode === "binary"
        ? [
            "Deine OGS hält nur fest, ob ein Kind da ist. Dann wirkt hier nur die `Geräte-PIN`.",
            "Die Knöpfe zum Auschecken und die Einstellungen zu `nach Hause` ändern bei dir nichts.",
          ]
        : []),
      "Arbeitet deine OGS ohne NFC, gibt es den Bereich `Geräte` in den `Einstellungen` nicht.",
      "Die `Geräte-PIN` darf nur ändern, wer die OGS verwaltet.",
    ],
    troubleshootingDetails: [
      "Die neue PIN klappt am Tablet nicht? Starte das Tablet neu.",
      "Du findest den Bereich `Geräte` nicht? Dann arbeitet deine OGS ohne NFC.",
    ],
    related: [
      HELP_TOPICS.nfcCheckIn,
      HELP_TOPICS.leadDevices,
      HELP_TOPICS.settings,
      HELP_TOPICS.leadTabletSetup,
    ],
  };
} satisfies typeof authored_nfcSettingsTopic;

